<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{Clock,Search,TrendCharts,Wallet}from'@element-plus/icons-vue';import{getChargingHistory}from'@/api/chargingStationsApi';import{useUserStore}from'@/stores/user';
const store=useUserStore(),loading=ref(false),rows=ref<any[]>([]),keyword=ref('');const format=(v:any)=>v?String(v).replace('T',' ').slice(0,16):'—';const duration=(r:any)=>r.durationMinutes??r.duration_minutes??0;const filtered=computed(()=>rows.value.filter(r=>`${r.stationName||''}${r.stationId||''}`.toLowerCase().includes(keyword.value.toLowerCase())));const totalMinutes=computed(()=>rows.value.reduce((n,r)=>n+Number(duration(r)||0),0));const totalAmount=computed(()=>rows.value.reduce((n,r)=>n+Number(r.totalAmount??r.amount??0),0));onMounted(async()=>{if(!store.user?.id)return;loading.value=true;try{const r:any=await getChargingHistory(store.user.id);rows.value=Array.isArray(r?.data)?r.data:[]}catch{ElMessage.error('充电记录加载失败')}finally{loading.value=false}})
</script>
<template><div class="history-page"><header class="page-header"><p>CHARGING ACTIVITY</p><h1>充电记录</h1><span>查看你的历史充电与消费情况</span></header><main class="history-main"><section class="stats"><article><Clock/><div><small>累计次数</small><strong>{{rows.length}} 次</strong></div></article><article><TrendCharts/><div><small>累计时长</small><strong>{{Math.round(totalMinutes/60*10)/10}} 小时</strong></div></article><article><Wallet/><div><small>累计费用</small><strong>¥{{totalAmount.toFixed(2)}}</strong></div></article></section><section class="table-card"><div class="table-head"><div><h2>历史明细</h2><p>充电订单按时间排列</p></div><el-input v-model="keyword" :prefix-icon="Search" clearable placeholder="搜索站点"/></div><el-table v-loading="loading" :data="filtered" empty-text="暂无充电记录"><el-table-column label="开始时间" min-width="160"><template #default="{row}">{{format(row.startTime||row.start_time)}}</template></el-table-column><el-table-column label="充电站" min-width="160"><template #default="{row}"><strong>{{row.stationName||`充电桩 #${row.stationId||row.station_id}`}}</strong></template></el-table-column><el-table-column label="时长" min-width="100"><template #default="{row}">{{duration(row)}} 分钟</template></el-table-column><el-table-column label="费用" min-width="100"><template #default="{row}">¥{{Number(row.totalAmount??row.amount??0).toFixed(2)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default><el-tag type="success" effect="light">已完成</el-tag></template></el-table-column></el-table></section></main></div></template>
<style scoped>.history-page{min-height:calc(100vh - 72px);padding-bottom:40px;background:var(--surface-muted)}.page-header p,.page-header h1,.page-header span{margin:0}.page-header p{color:var(--brand);font-size:11px;font-weight:800;letter-spacing:.11em}.page-header h1{margin:7px 0 9px}.page-header span{color:var(--text-secondary)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin-bottom:18px}.stats article{display:flex;align-items:center;gap:15px;padding:21px;background:#fff;border:1px solid var(--border-color);border-radius:16px}.stats article>:deep(svg){width:26px;color:var(--brand)}.stats small,.stats strong{display:block}.stats small{color:var(--text-muted);font-size:11px}.stats strong{margin-top:6px;font-size:20px}.table-card{padding:24px;background:#fff;border:1px solid var(--border-color);border-radius:18px;box-shadow:var(--shadow-sm)}.table-head{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:20px}.table-head h2,.table-head p{margin:0}.table-head h2{font-size:20px}.table-head p{margin-top:5px;color:var(--text-muted);font-size:11px}.table-head .el-input{max-width:280px}@media(max-width:650px){.stats{grid-template-columns:1fr}.table-card{padding:17px}.table-head{align-items:stretch;flex-direction:column}.table-head .el-input{max-width:none}}</style>
